SELECT MIN(icustays.los) AS min_los FROM icustays JOIN patients ON icustays.subject_id = patients.subject_id WHERE patients.gender = 'F' AND patients.anchor_age = 86 AND (icustays.stay_id IN (SELECT hadm_id FROM emar WHERE medication IN ('hydralazine', 'isosorbide dinitrate')) AND (SELECT COUNT(*) FROM diagnoses_icd WHERE icd_code IN (SELECT icd_code FROM d_icd_diagnoses WHERE long_title BETWEEN '81' AND '91')));